def redact_headers(headers: dict):
    sensitive = {'authorization', 'cookie', 'x-api-key'}
    redacted = {
        key: '[redacted]' if str(key).casefold() in sensitive else str(value)
        for key, value in headers.items()
    }
    redacted_fields = sorted(
        str(key) for key in headers if str(key).casefold() in sensitive
    )
    return {'headers': redacted, 'redacted_fields': redacted_fields}
